def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    T = data[0]
    N = int(data[1])
    S = []
    for i in range(2, 2 + N):
        tmp = data[i].split()
        S.append(tmp)

    INF = 10**18
    dp = [([0] + [INF] * len(T)) for _ in range(N + 1)]

    for i in range(1, N + 1):
        dp[i] = dp[i - 1][:]

        for s in S[i - 1]:
            for j in range(len(T) + 1):
                post_len = j + len(s)
                if post_len > len(T):
                    continue

                if T[j:post_len] == s:
                    dp[i][post_len] = min(dp[i][post_len], dp[i - 1][j] + 1)

    if dp[N][len(T)] == INF:
        print(-1)
    else:
        print(dp[N][len(T)])

    return
